/* DM-only, original transition preparation. Selecting a branch never establishes an outcome. */
(() => {
  'use strict';
  const lmop = page => ({book:'lmop',page,label:'Lost Mine of Phandelver (2014)',note:'Printed page; verified against the existing Wave Echo runbook.'});
  const mage = page => ({book:'madMage',page,label:'Dungeon of the Mad Mage (2018)',note:'Printed page; setting anchor verified in the existing Waterdeep expedition reference.'});
  const custom = 'Original Echo Below scene and dialogue; future preparation, not an event that has happened.';
  const option = (value,label,read,run,consequences) => ({value,label,read:read?[read]:[],run:run||[],consequences:consequences||[]});
  const unknown = subject => option('unknown','Not yet confirmed','',[
    'Ask for the last confirmed information about '+subject+'. Keep rumors and private truth separate from what the party has learned.',
    'Use the neutral homecoming. Do not announce a rescue, death, reward, reopened mine, or item transfer.'],[
    'The question stays open. Preparing a future scene does not change the outcome ledger or publish a clue.']);
  const outcomes = [
    {id:'gundren',title:'Gundren Rockseeker',prompt:'What happened to Gundren, where is he now, and who has actually learned that?',source:[lmop(51)],options:[
      unknown('Gundren'),
      option('rescued','Alive and rescued','Gundren’s rescue is part of the account you can now give. His next steps depend on where he is, what he needs, and what he has actually learned.',[
        'Confirm Gundren’s present location before placing him in this scene. If he is present, he can ask: “Before we speak about the mine, tell me whose help we still owe.” Ask what he knows about his brothers before introducing their news.',
        'He can request a safe route, a report, or a meeting. He does not award ownership of discoveries someone else holds.'],['Record his actual location, agreed help, and only the information the party gives him.']),
      option('missing','Still missing or captive','A space has been left at the table. No one has decided what to say about it.',[
        'List the last reliable sighting and the remaining rescue lead. The privately established castle delivery does not become public merely through this branch.',
        'Waterdeep can provide specialist help if the party chooses, but leaving is a real decision with a return plan.'],['A rescue objective remains open; no automatic death, transfer, or forfeited reward.']),
      option('dead','Death confirmed','The first question is not about treasure. It is who should be told, and who should hear the news in person.',[
        'Let the party choose remembrance, returning identified possessions, and contacting living relatives. Avoid speaking for a survivor whose fate is unknown.',
        'Trista may answer privately or decline a spotlight about her benefactor.'],['Record notified people and custody of belongings. Any estate or mine agreement needs a living, legitimate decision-maker.']),
      option('elsewhere','Alive elsewhere or unavailable','A reliable address would make the next message possible. Until then, news and intended recipients remain separate questions.',[
        'Use the actual location and relationship. Prepare a letter, trusted messenger, or later meeting rather than placing him in Phandalin automatically.'],['A message records intended recipient, contents, delivery method and unresolved receipt.'])]},
    {id:'nundro',title:'Nundro Rockseeker',prompt:'Was Nundro reached, rescued, and brought to safety? What care and location are confirmed?',source:[lmop(50),lmop(51)],options:[
      unknown('Nundro'),
      option('rescued','Alive and rescued','Nundro’s rescue can be reported without deciding his next journey for him. There is still room to ask what care he needs and whom he wants told.',[
        'Confirm Nundro’s present location before placing him in this scene. If present and willing, he can say: “I can tell you what I remember. Give me a moment to put it in order.” Offer care and a private reunion only if the relevant people are present. His account covers captivity, not every room of the mine.',
        'Review the printed survival award once; do not award again from a transition card.'],['Record recovery needs, location and any requested accompaniment. He is not automatically an expedition combatant.']),
      option('missing','Not yet found or rescued','Nundro’s last known situation remains an unfinished part of the account. What would establish where he is now?',[
        'Distinguish never reached, observed but not extracted, and left with a named protector. Use the last recorded state.',
        'Offer return, local assistance, or a specific rescue-support inquiry. No elapsed-time execution is presumed.'],['Keep rescue and safe extraction unresolved; departure requires a stated plan if the party chooses to leave.']),
      option('dead','Death confirmed','A quiet place is made for the news. For a while, no one asks what the expedition earned.',[
        'Agree how the body or personal effects are handled and which living relatives receive the news. Let silence and practical help carry the scene.'],['Record care for the dead and notifications. No Nundro survival reward.']),
      option('elsewhere','Alive in other care','There is a message to send before there is a celebration to arrange.',[
        'Name the actual caregiver or safe location. Ask whether the party has permission to pass on medical or personal information.'],['Confirm transport, supplies or a promised check-in through the normal outcome workflow.'])]},
    {id:'nezznar',title:'Nezznar and remaining opposition',prompt:'Is Nezznar dead, captured, escaped, bargained with, or still unencountered? Record the last verified place and resources.',source:[lmop(50)],options:[
      unknown('Nezznar'),
      option('dead','Death confirmed','Nezznar’s death settles his fate. It does not settle which parts of his work remain.',[
        'Use an available informed listener, not an assumed living Sildar. Review surviving associates, traps, debts and documents without reviving the villain.',
        'Notes are a possible lead only if recovered and readable. They are not an omniscient confession.'],['Close only the related outcome after approval; rescue, mine safety and custody remain separate.']),
      option('captured','Alive in custody','Custody leaves practical questions: where is Nezznar held, who has accepted responsibility, and what must be arranged before you leave?',[
        'Use the actual captor, cell, seized equipment and guard arrangements. The published Phandalin route is a Lords’ Alliance escort to Neverwinter; Waterdeep is not the default prisoner destination.',
        'The printed Halia escape scheme needs an opportunity. Posted guards and precautions matter; no unavoidable jailbreak cutscene.',
        'Keep Nezznar’s claims separate from corroborated evidence. He has no established authority on Halaster or Aldric.'],['Agree written handover and responsibility before departure. No automatic escort, escape or doubled repeat XP.']),
      option('escaped','Escaped; location uncertain','His last verified movement matters more than a guess about his destination. What did you actually see?',[
        'Preserve last sighting, followers, wounds, resources and stolen items. Offer watch notices, pursuit or a bounded inquiry.',
        'Do not give him new powers or information to guarantee his return.'],['Propose a survivor plan for DM review; leaving town does not trigger a predetermined attack.']),
      option('bargain','A bargain is still in force','The terms still matter. Which promises were made, which have been kept, and what remains uncertain?',[
        'Read the actual terms, witnesses, collateral and expiry. Distinguish intended betrayal from a betrayal that has happened.',
        'Offer safeguards, renegotiation or refusal with foreseeable consequences.'],['Keep obligations and unresolved trust visible; no automatic alliance or quest completion.']),
      option('active','Still active or not confronted','No one calls the road clear. The question is what can be done safely with the information you have.',[
        'Returning to unfinished Phandelver work remains the clearest option. Research or support from Waterdeep can be sought without declaring the mine recovered.'],['Track a return purpose and contact. Review any intervening enemy action before recording it.'])]},
    {id:'mine',title:'The mine and Forge',prompt:'What areas are known, which hazards remain, who may authorize work, and was the Forge actually examined?',source:[lmop(48),lmop(51)],options:[
      unknown('the mine'),
      option('secured','A working safety assessment supports reopening','A route used by adventurers will be asked to carry other lives. Which passages have actually been assessed for that work?',[
        'Use actual cleared routes and remaining hazards; defeating Nezznar alone is not a safety survey.',
        'If Gundren and Nundro live and the printed successful conclusion fits, they can offer 10 percent of future profits. Profits must first exist; altered circumstances require a new agreement.'],['Record authorized access, operators, unresolved hazards and the actual contract. No immediate gold or automatic ownership.']),
      option('partial','Partly explored or still dangerous','The known passages and unanswered questions belong in the same account. Neither should be mistaken for the other.',[
        'Publish a practical warning only with the party’s approval. Assign an actual person to any entrance watch they request.',
        'Preserve rooms, survivors, loot and temporary effects for a return.'],['Mine remains unfinished; reopening, profits and blanket clearance are unavailable claims.']),
      option('contested','Control or access is disputed','Control of the mine is still disputed. A route, a claim and permission to use it are three different things to establish.',[
        'Name the real claimants, evidence and capacity to act. Rescue, access, ownership and research permission can be negotiated separately.',
        'A Waterdeep inquiry can seek advice but does not confer authority over Phandalin.'],['Record terms and temporary access. Do not invent a property award or faction annexation.']),
      option('sealed','Access deliberately restricted','Restricted access leaves a question for anyone who comes after you: what is the danger, and who can decide when it is safe to enter?',[
        'Record who agreed, what barrier or watch actually exists, who can authorize entry, and when to review the restriction.',
        'Sealing an entrance does not prove every inhabitant escaped; check prisoners and creatures separately.'],['Maintain an inspection or revisit option. Conditions change only through approved events.']),
      option('destroyed','Destroyed or presently unusable','The mine can no longer be used as it was. The next account must distinguish what was lost from what can still be recovered.',[
        'Use only a confirmed destruction or damage record. Identify its actual extent: entrance, route, work area, Forge or the whole site. Do not turn a collapsed passage into a destroyed mountain.',
        'Check people, possessions and escape routes separately. A destroyed or unusable mine does not establish any death, trapped person, lost artifact or failed rescue.',
        'Offer assessment, warning, recovery, repair or leaving the site secured. A Waterdeep inquiry may seek expertise, but cannot guarantee restoration or income.'],['Record the observed damage and permitted access. Suspend unsupported reopening or profit claims; preserve unresolved fates and custody.'])]},
    {id:'prisoners',title:'Prisoners, rescued people and escorts',prompt:'List people individually: current state, place, immediate care, consent, escort and responsible contact.',source:[lmop(50)],options:[
      unknown('prisoners and people needing help'),
      option('safe','Known people safely returned or cared for','Each confirmed return has its own name, destination and next need. Review them one at a time.',[
        'Use individual approved records. Redbrand captives, Nundro and any captured enemies have different needs and custodians.',
        'Ask what help was promised and whether that person wants their account shared.'],['Record actual reunions and handovers separately; no mass rescue inferred.']),
      option('escort','People still need care or escort','Safe travel requires more than choosing a destination. Who has agreed to accompany each person who still needs help?',[
        'Offer accompanying them, arranging a trusted escort, or delaying departure. Establish destination, provisions and consent.',
        'A contact accepts responsibility only after a real conversation.'],['Keep handover open until completed. Do not move NPCs merely by selecting a plan.']),
      option('held','Captives remain held','The names still missing are copied onto a separate page, where they cannot disappear among completed errands.',[
        'Record last seen conditions and credible options for rescue, bargaining or outside assistance. Declining a lead does not establish anyone’s death.'],['Keep an actionable return lead and review any deadline with evidence.']),
      option('none','Reviewed; no unresolved prisoner obligations','The list is checked a final time. No one adds another name.',[
        'Use only after individual records were reviewed. This is a summary, not a command to remove open rescues.'],['If new evidence appears, reopen the relevant individual question.'])]},
    {id:'promises',title:'Promises, debts and unfinished work',prompt:'Who was promised what, by whom, by when, and who knows the agreement?',source:[],options:[
      unknown('promises and debts'),
      option('open','Outstanding obligations','There are still promises that need an answer. What should their recipients know before the party leaves?',[
        'List exact commitments from play, including Yeemik only if the existing bargain has further terms. Do not add tribute or service to his recorded release bargain.',
        'Offer fulfilment, renegotiation, a willing delegate, or honest notice of delay.'],['Keep each promise’s owner and status distinct; choosing Waterdeep does not complete any of them.']),
      option('settled','Reviewed and settled','Receipts and returned messages make a small, untidy pile. There is room on the table for another map.',[
        'Verify the individual outcomes and disputed payments. A missing response is not agreement.'],['No automatic currency changes or additional rewards.']),
      option('deferred','Delay or delegation agreed','The accepted changes to the promise belong beside its original terms. What was agreed, and when should it be reviewed?',[
        'Record the actual accepted terms, contact, contingency and next review. If nobody accepted, keep the promise open instead.'],['Use the existing calendar only after a date and elapsed time are approved.'])]},
    {id:'custody',title:'Discoveries, copies and important possessions',prompt:'For each object or record: owner, present holder, permitted readers/tests, copies, return terms and evidence of transfer.',source:[],options:[
      unknown('discovery custody'),
      option('party','Party retains specified discoveries','Blank labels lie beside the packs. There is space for a name, an owner, and a line saying what may be done with what is inside.',[
        'Work item by item. Trista’s BELOW token remains private; Echo’s Whisper is a separate medallion and may never have been acquired.',
        'Record mine maps, samples and Nezznar notes only if recovered. Taking a copy is not permission to publish the original.'],['A research lead can use a redacted observation without handing over an object.']),
      option('shared','Specific copies or examinations authorized','Permission has boundaries: which part may be copied, who may see it, and what remains with its owner?',[
        'Name recipient, allowed content, tests, credit, return date and restrictions. Ask the owner before exposing private information.',
        'Do not assume Mara, Dracuseth, Selise or the party knows Trista’s token exists.'],['Only the approved copy or disclosure becomes a publishable event.']),
      option('other','Held by another person or secured locally','The receipt names where the object is, and leaves room for a second signature when it changes hands.',[
        'Use the recorded holder and access terms. Research can proceed by correspondence or a permitted sketch.',
        'A traveling party does not automatically carry the Forge, every discovery, or someone else’s property.'],['Track access or retrieval as a lead; do not duplicate an inventory object.']),
      option('disputed','Missing or disputed custody','Two accounts describe the same object in different hands. The next useful question is when anyone last saw it.',[
        'Preserve both claims, last confirmed sighting and actual evidence. Investigate without choosing an owner silently.'],['Keep transfer unresolved. Offer a records inquiry or recovery lead without guaranteeing theft or culprit.'])]}
  ];
  const leads = [
    {id:'research',title:'A second opinion at the Second Margin',scene:'wd-research',media:['recorded-investigation'],questIds:['echo-below','second-opinion','character-donavan','character-trista'],beatIds:['tr-leads','wd-research'],
      availableWhen:'A genuine observation, copied mine record, recovered note, or research question is available and its owner authorizes the proposed disclosure. No medallion is required.',
      offer:'Ask Selise Ardent for a bounded comparison and a written account of what remains uncertain. A letter can request the meeting before travel.',
      read:['“Send the observation first,” reads the proposed inquiry. “What happened, who saw it, and what you are willing to have examined. We can discuss explanations afterward.”'],
      ask:['What single question do you want tested? Who may receive the answer?'],
      choices:['Bring a permitted sample or copy.','Send a redacted letter and wait in Phandalin.','Decline examination and seek ordinary work instead.'],
      consequences:['An accepted inquiry creates a meeting and testable question, not a revelation about Looking Glass.','Fees, copying, credit and experiments need agreement; no object changes custody from accepting the lead.'],
      alternative:'If no relevant mine evidence is recovered, use Donavan’s own field observation or an ordinary comparative question. If nobody wants research, use the work or contact leads.',source:[lmop(47)],sourceNote:'The future-map hook on p.47 is published. A Waterdeep annotation, Selise, research correspondence and all dialogue are custom.'},
    {id:'work',title:'Paid route work through the Yawning Portal',scene:'wd-portal',media:['recorded-tavern'],questIds:['act-home','route','character-ringgo','character-pebble'],beatIds:['tr-leads','tr-next','wd-brief'],
      availableWhen:'The party wants legitimate work and can request an introduction. Dracuseth, a contacted Portal patron, or a willing correspondent can put them in touch; no relationship is assumed completed.',
      offer:'Ilvara Reed can discuss a survey of one bounded stretch of Undermountain, with agreed pay, useful reporting even after retreat, and explicit turnaround conditions.',
      read:['“A clear account of where you stopped is worth more to me than a brave story with the dangerous part left out.”'],
      ask:['What counts as delivery, who owns the map, and when would you turn back?'],
      choices:['Arrange an interview in Waterdeep.','Request surface work while recovering or preparing.','Decline the patron and keep the city visit personal.'],
      consequences:['No descent is booked and no payment awarded until terms are agreed.','Review actual party readiness before the main dungeon, normally around level 5; arrival does not level anyone up.'],
      alternative:'A modest surface delivery or witness interview can establish a professional reference first. This needs agreed terms and is not a compulsory substitute adventure.',source:[mage(6),mage(7)],sourceNote:'The Portal expedition setting is published. Ilvara’s survey commission and its terms are original campaign preparation.'},
    {id:'makers',title:'A craft question for Ninepin Works',scene:'wd-research',media:['recorded-investigation'],questIds:['instrument','character-pebble','character-aldric'],beatIds:['tr-leads','wd-workshop'],
      availableWhen:'Pebble wishes to inquire about his hammer-makers, or an owner permits inspection of an ordinary tool, sample or signet. A recovered magical object is unnecessary.',
      offer:'Orren Brassmantle can compare a maker’s mark without damaging the object and identify the next kind of record to seek.',
      read:['“A good mark tells you where to begin looking. It is not a whole history pressed into metal.”'],
      ask:['What do you allow inspected? What would you like to learn about the maker rather than the magic?'],
      choices:['Visit with the owner and keep the object in sight.','Send a drawing with an agreed return address.','Ask home for a corroborating description before traveling.'],
      consequences:['A matching detail creates a lead, not proof of the missing colleague’s fate.','Aldric can request a discreet signet comparison without naming his past publicly. No memory or Halaster revelation is granted.'],
      alternative:'If marks cannot be compared yet, Orren can discuss maintenance, ordinary mineral identification, or where suitable trade records are kept.',source:[],sourceNote:custom},
    {id:'contact',title:'An address and an ordinary beginning',scene:'wd-contact',media:['recorded-town'],questIds:['act-home','courtyard','character-ringgo','character-aldric'],beatIds:['tr-leads','tr-dracuseth','tr-courtyard'],
      availableWhen:'Someone chooses to contact Dracuseth at the Yawning Portal, or asks there after arriving. He remains a Waterdeep contact and has not been accompanying the party.',
      offer:'Dracuseth can arrange a table and introduce lodgings around a shared courtyard. Ask separately for civic records, healing or paid-work introductions.',
      read:['“Come if the city has something you want. I can help you find a door and someone worth speaking to. The rest should be your decision.”'],
      ask:['What ordinary thing would make the city useful: a room, mail, work, care, or an introduction?'],
      choices:['Send a message and proposed arrival window.','Arrive without notice and leave a message.','Stay in Phandalin; keep the address for later.'],
      consequences:['No emergency, debt, faction membership or property award comes with the invitation.','If Sildar is alive, present and willing, he may provide a factual reference; his involvement is optional.'],
      alternative:'Durnan can provide practical lodging information or take a message. Dracuseth need not appear instantly, and the party can choose another home.',source:[mage(6)],sourceNote:'The Portal is published; Dracuseth and the courtyard offer are custom.'}
  ];
  const beats = [
    {id:'tr-reconcile',title:'Before the transition · decide what is actually known',scene:'town-phandalin',media:[],questIds:['act-prologue','gundren','wave-echo'],read:[],
      tv:'Keep the current player display or a known town view. This preparation card is private.',
      ask:['What is the current stopping point? Which of the seven outcome questions have approved answers?','Is the party finishing Phandelver, seeking help before returning, or merely considering a later journey?'],
      run:['Latest confirmed play leaves Gundren at an unnamed inn after Glasstaff put him to sleep; Trista holds the captured rat, Glasstaff escaped, and the party stopped at Barthen’s Provisions. Gundren’s present condition is unreported. All scenes in this pack are future branches until played; opening this pack never completes Phandelver.',
        'Review approved outcomes for Gundren, Nundro, Nezznar, the mine, prisoners, promises and custody. Link evidence for each selected branch. Leave unknown answers unknown.',
        'Use the homecoming appropriate to the actual return: complete success, a mixed result, unresolved expedition, or a visit for aid. Review Sildar, Iarno, Redbrands and other returning NPCs individually.',
        'Select at most two of the four city leads to present now. Keep the others available if the party declines or cannot use one.',
        'Recheck current character resources, real level and carried items through existing sheets. No rewards, rests, inventory transfers or elapsed days occur from staging scenes.'],
      choices:['Continue Phandelver using its current saved state.','Prepare a conditional future return.','Run an actual return once its outcomes are approved.'],
      private:[custom,'Latest approved campaign outline supersedes older automatic Forge attention or instant medallion revelations. Only an actual relevant interaction can justify Halaster noticing remotely; this pack reveals none of that.'],source:[lmop(51)],
      decisions:[{label:'Outcome unknown',consequence:'Use neutral narration and keep the question open.'},{label:'Outcome approved',consequence:'Preview its matching response; publishing or updating quests remains a separate reviewed action.'}]},
    {id:'tr-homecoming',title:'Phandalin homecoming · the account before the celebration',scene:'town-phandalin',media:['recorded-town'],questIds:['act-prologue','gundren','wave-echo'],
      tv:'Start with the known Phandalin map. The celebratory lmop-phandalin-homecoming illustration is optional only after the actual mood fits.',
      read:['The familiar roofs appear beyond the fields. A worker rests both hands on a fence and watches your approach. By the time you reach the first houses, the question has traveled ahead of you: what news have you brought?'],
      ask:['Who do you see first? Which news belongs in public, and which should be told privately?','What do you want the town to understand—and what are you still uncertain about?'],
      run:['Let the first available familiar resident ask for the party’s account. Use Barthen if available; use another established contact if not. Their aim is practical certainty about people, supplies and danger.',
        'Use the chosen outcome responses without reading every possible branch. A reunion requires both people alive, present and willing; a memorial requires confirmed loss; a celebration requires a reason the town actually knows.',
        'A successful mine claim still needs a safety and stewardship discussion. A partial return can include gratitude for someone saved and a request for help with someone still missing.',
        'Give every player one invitation: something they say, something they keep private, or someone they seek. Passing is a valid answer.',
        'Capture the public account as a draft recap. Do not include the private token, the castle destination before learned, or future Waterdeep theories.'],
      choices:['Public report at a familiar gathering place.','Separate private visits with affected people.','Care and rest first; arrange the account later.'],
      private:[custom,'Existing homecoming art may imply success; a neutral town map works for every result.'],source:[lmop(51)],
      decisions:[{label:'Public account',consequence:'Only approved, deliberately shared facts become town knowledge.'},{label:'Private visit',consequence:'Record each recipient; other residents remain uninformed.'},{label:'Wait',consequence:'Choose a meeting time without inventing a penalty for needing recovery.'}]},
    {id:'tr-obligations',title:'Around the table · people, promises and custody',scene:'lmop-stonehill-common-room',media:['recorded-fire'],questIds:['act-prologue','gundren','wave-echo','character-trista'],
      tv:'Use a neutral room illustration; private contracts, captive information and possessions stay in DM notes unless shared.',
      read:['A cleared table fills with the things a journey leaves behind: a folded message, a borrowed tool, a list of names. Outside, ordinary work continues. Here, you have time to decide what must happen before another road is taken.'],
      ask:['Who still needs help or an answer? Who is holding each important object?','What can you settle now, what requires a willing helper, and what must wait?'],
      run:['Invite only NPCs actually available and allowed to hear this discussion. A host wants rooms and promises settled; a mine representative wants realistic access; a caregiver wants an accepted handover.',
        'Review people individually: rescued Redbrand prisoners, any surviving Rockseekers, captured opponents and companions. No person is an item in a bulk transfer.',
        'If Nezznar is held, use the custody branch. The printed escort goes toward Neverwinter. Record guards and handover rather than silently taking him to Waterdeep.',
        'Review mine stewardship separately from loot. The printed successful profit offer is future income, conditional on matching circumstances; altered outcomes require agreed terms.',
        'Make a custody list by object: original, copies, holder, access permission, promised return and who knows. Trista’s BELOW token and Echo’s Whisper remain distinct. A letter or sketch can travel instead of an original.',
        'Use the outcome review to apply actual promises or transfers together. Preparing the meeting changes nothing by itself.'],
      choices:['Settle one obligation before leaving.','Ask a willing person to take a defined responsibility.','Leave the question open and choose a return date.'],
      private:[custom,'Use owner-only channels for personal disclosure. Dracuseth receives only what the party later tells him.'],source:[lmop(50),lmop(51)],
      decisions:[{label:'Accepted handover',consequence:'Record both parties, place and terms; update only the linked custody or promise.'},{label:'Unanswered request',consequence:'Retain an unresolved request, never a completed agreement.'}]},
    {id:'tr-leads',title:'A reason to go · choose the city’s first two doors',scene:'town-phandalin',media:['recorded-town'],questIds:['echo-below','act-home','second-opinion','route','courtyard'],
      tv:'Show a player-safe objective or known town scene. Preview any letter before deliberately publishing it; future research answers stay private.',
      read:['There are several ways to begin another journey: a question on a clean page, work that needs doing, or the address of someone willing to meet you. None of them tells you what you must leave behind.'],
      ask:['What do you want from Waterdeep that you cannot reasonably get here?','Which two leads would be useful even if your first idea turns out to be wrong?'],
      run:['Choose two available lead cards: Second Margin research, Portal route work, Ninepin craft inquiry, or Dracuseth’s practical introduction. Keep the other two as alternatives.',
        'Give every invitation an actual carrier: an approved outgoing letter and later answer, a willing existing contact, or an inquiry made on arrival. A new letter has not already arrived.',
        'A recovered Mormesk map or Nezznar note can supply a Waterdeep connection only if it was actually recovered and the custom annotation is introduced. The scene also works when neither exists.',
        'No source knows Looking Glass’s answer yet. Selise offers method; Orren offers comparison; Ilvara offers terms; Dracuseth offers a meeting.',
        'Add chosen leads to the session preparation board. Publish only the lead summary the players actually hear. Main objective stays on TV; side and owner character quests use their existing phone audiences.'],
      choices:['Follow two city leads.','Seek information by letter while staying here.','Choose another destination or continue unfinished Phandelver work.'],
      private:[custom,'The city is a useful opportunity, not an emergency summons designed to force departure.'],source:[lmop(47),mage(6)],
      decisions:[{label:'Accept a lead',consequence:'Prepare its meeting and terms, with no automatic quest completion or disclosure.'},{label:'Decline a lead',consequence:'Offer another credible contact or respect a decision to stay.'}]},
    {id:'tr-delay',title:'If they stay · a useful day in Phandalin',scene:'town-phandalin',media:['recorded-town'],questIds:['act-prologue','wave-echo','courtyard'],
      tv:'Keep Phandalin visible and a simple chosen local objective. Do not replace it with a departure banner.',
      read:['Morning starts with familiar sounds: a cartwheel in a rut, a door being unlatched, somebody calling across the street. There is work here that will still matter after the next great adventure has a name.'],
      ask:['What would make leaving feel responsible?','Do you want to help someone, secure a route, follow a missing person, repair equipment, or rest?'],
      run:['Offer two tasks grounded in actual unresolved records: escort a person who needs it, finish an agreed delivery, survey a safe route, visit a recovering contact, return identified belongings, or investigate an open rescue lead.',
        'If the party has no outstanding obligation, invite one self-chosen improvement or ordinary downtime project. Staying requires no justification.',
        'Stage the existing relevant town or dungeon scene. Reuse actual persistent room and enemy states; do not reset a finished fight to fill the evening.',
        'Send an honest postponement to any accepted city appointment. Decide whether the recipient can accommodate it when the response arrives.',
        'Advance time and review any established deadline only after the DM approves elapsed time. A delay alone does not kill a prisoner, burn a home or activate Halaster’s project.'],
      choices:['One local task, then revisit departure.','Recover and correspond for an agreed period.','Make Phandalin the current base and leave Waterdeep as a later lead.'],
      private:[custom,'This is a complete valid branch. No Waterdeep quest or character story is forfeited by using it.'],source:[],
      decisions:[{label:'Stay',consequence:'The next session board centers the selected local objective.'},{label:'Postpone a meeting',consequence:'Record the message and proposed date; no automatic acceptance.'}]},
    {id:'tr-departure',title:'Departure · an agreed road and a way back',scene:'region-lmop',media:['recorded-journey'],questIds:['act-home','courtyard','character-pebble'],
      tv:'Use the known frontier map for the first leg only. It does not map the complete road to Waterdeep; keep unknown regional markers concealed.',
      read:['At the edge of town, the road looks ordinary again. Packs settle, straps tighten, and the first turn waits for a choice. Behind you are people who know your names. Ahead is a city where introductions still matter.'],
      ask:['Who has the route, who keeps the travel record, and where can a message catch you?','Which obligations and people remain here, and when will you check on them?'],
      run:['Custom default itinerary: the known road from Phandalin to the Triboar Trail, then west to the High Road and south toward Waterdeep. Confirm actual road conditions and stops before accepting it. Neverwinter or an inland Amphail visit is a deliberate detour, not a stop silently inserted into every journey.',
        'Define route segments and distances in the existing travel planner before quoting a numeric ETA. The painting is approximate; this pack does not supply an invented total mileage or travel duration.',
        'Agree foot, mount, wagon or a contracted caravan, pace, provisions, weather, watch plan and named stops. Vessel travel requires arranging a real departure port and passage separately.',
        'Review responsibility for dependents, prisoners and discoveries. A caravan leader agrees any escort or guarded cargo explicitly.',
        'Pebble may make a route mark or sketch with the group’s help. Donavan may prepare a letter; Ringgo may review terms; Trista and Aldric decide what travels privately.',
        'Make a restore point. Begin the journey only after the table chooses it; no sheets, travel clocks or towns change merely from staging this card.'],
      choices:['Travel independently by an agreed route.','Negotiate a place with a caravan.','Return to preparations or delay departure.'],
      private:[custom,'Regional route is a custom itinerary using known roads, not a surveyed distance. No mandatory random fight.'],source:[],
      decisions:[{label:'Choose a route',consequence:'Review its estimates and costs before committing travel.'},{label:'Hire help',consequence:'Agree an actual price, responsibility and destination; do not invent a paid contract retroactively.'}]},
    {id:'tr-road',title:'On the road · a wheel that will not turn',scene:'cover',media:['recorded-journey'],questIds:['act-home','character-pebble','character-ringgo'],
      tv:'Use the campaign cover as neutral road staging. Existing ambush art contains misleading bodies/enemies; do not reuse it as an empty road.',
      read:['A loaded wagon leans into the verge, one wheel sunk at an awkward angle. Two travelers have spread a blanket for the unloaded goods. A third holds up a broken length of wood and gives it a look no amount of optimism is going to improve.'],
      ask:['Do you stop, ask what help is needed, or continue?','What would make a repair safe enough for everyone who must travel on it?'],
      run:['Optional original complication on a road segment the DM selected. Edda Vale, a practical independent carrier, wants to protect her cargo and workers; she is neither an ambusher nor secretly an Echo agent.',
        'The visible problem is a cracked wheel support after a deep rut. A competent practical plan, available materials and help can work without a roll; use a fitting check only when the outcome is uncertain and failure has a clear consequence.',
        'Possible approaches: unload and brace for a short move to safety; carry a request to the next established stop; offer a suitable spare; negotiate paid labor; wait together; politely continue.',
        'Before a roll or expenditure, state the time, materials and risk. Failure costs an agreed delay or needs a different repair; it does not suddenly cause lethal injury.',
        'News from Edda is a dated traveler’s claim with a named source, not confirmation of every Phandalin event. If the party helps, she can later recognize them in the city; record the actual name and promise.',
        'No stat block or combat encounter is required. If the party provokes violence, pause to stage a suitable encounter using existing creature tools and actual participants.'],
      choices:['Repair or stabilize the wagon.','Arrange assistance and keep moving.','Decline with or without sharing road information.'],
      private:[custom,'This traveler is a new optional NPC proposal, not an existing friend. Helping does not create a permanent debt or a free cargo reward.'],source:[],
      decisions:[{label:'Help',consequence:'Approve the actual delay/cost and a limited relationship or payment if agreed.'},{label:'Arrange help',consequence:'Record a message or commitment; the wagon is not repaired until help arrives.'},{label:'Continue',consequence:'The journey proceeds; no retaliation is manufactured.'}]},
    {id:'tr-camp',title:'A night on the journey · what travels with you',scene:'cover',media:['recorded-fire','recorded-forest'],questIds:['act-home','character-donavan','character-aldric','character-trista','character-pebble','character-ringgo'],
      tv:'Use neutral cover art or black screen. Keep private letters and character questions off TV; ambience is optional.',
      read:['At the night’s stopping place, boots are set within reach and tomorrow’s route is checked once more. Beyond the small circle of conversation, the world continues without asking for an explanation. For a little while, there is time for an ordinary question.'],
      ask:['What do you want to be different when you next return?','Would you like to speak to someone, write a message, keep watch quietly, or skip to morning?'],
      run:['Use a stop actually chosen: a safe camp, rented room or caravan halt. Adjust the description to weather and shelter; do not require a fire or trigger Aldric’s smoke distress without Bowman’s participation.',
        'Offer a single spotlight to someone who has had less attention. Donavan may write Dianna a bounded observation; Pebble can compare the route with his sketch; Ringgo can define useful honest work; Trista can keep or share a thought voluntarily; Aldric may choose a practical act of care or a private records question.',
        'No memory, secret revelation or fellowship speech is required. The remaining players may respond or let the moment pass.',
        'Review guards, light, supplies and rest using the existing group-rest tool. A scene change does not heal anyone or restore resources.',
        'Compress uneventful remaining legs into a brief travel account once route, elapsed time and supplies are reviewed. If weather changes, offer shelter, pace or delay choices rather than adding combat by default.'],
      choices:['A short conversation or private note.','A rest with actual recovery review.','Skip uneventful travel to the next chosen stop.'],
      private:[custom,'The BELOW token stays private unless Trista discloses it. Aldric’s family and resurrection truths remain unrevealed.'],source:[],
      decisions:[{label:'Share something',consequence:'Ask who heard it and whether it may enter a shared journal.'},{label:'Keep it private',consequence:'Use an owner note only if the player wants a record.'},{label:'Compress travel',consequence:'Approve elapsed time/resources, then stage arrival; do not award an automatic long rest.'}]},
    {id:'tr-threshold',title:'Waterdeep · choose a first destination',scene:'city-waterdeep',media:['recorded-town'],questIds:['act-home','courtyard'],
      tv:'Preview the existing Waterdeep overview. Introduce the Portal and already earned destinations; retain unrevealed location details privately.',
      read:['The road narrows between carts and handbarrows before the city opens around you. Bells answer from different directions. A porter lifts a parcel above the crowd and shouts an address as if everyone in the world ought to know it. For the first time in days, the route has more turns than the map can conveniently explain.'],
      ask:['What do you need first: rest, food, a message delivered, a meeting, or a place to put your packs?','Who asks for directions, and what do you choose to tell a stranger?'],
      run:['Let ordinary porters and shopkeepers have ordinary goals: finish work, give directions, charge agreed service prices. They do not recognize secret discoveries or demand a campaign confession.',
        'Offer at most two useful destinations now: the Portal for an agreed contact and lodging, plus the lead the party selected. Other city content stays available in the library.',
        'If Dracuseth was contacted, check the actual appointment. If not, the Portal can take a message. He does not know their route, arrival time or Phandalin outcomes automatically.',
        'Record arrivals and delivered letters through approved outcomes. No automatic research discovery, rental or faction enrollment.',
        'If someone still needs medical care or a prisoner arrangement, resolve the real responsibility before an inn scene. Do not move a Neverwinter escort to this city for convenience.'],
      choices:['Go to the Yawning Portal.','Visit a prearranged contact first.','Find ordinary rest or services before meeting anyone.'],
      private:[custom,'Dragon Heist city material can enrich later visits, but this arrival does not trigger its published opening attack or property reward.'],source:[mage(6)],
      decisions:[{label:'Follow the meeting',consequence:'Stage the appointment actually arranged.'},{label:'Rest first',consequence:'Agree cost and time; the next lead remains available.'}]},
    {id:'tr-portal',title:'The Yawning Portal · a table beside the unknown',scene:'wd-portal',media:['recorded-tavern'],questIds:['act-home','route'],
      tv:'Preview the existing Portal illustration; keep its well a location to consider rather than opening a dungeon map.',
      read:['Warm conversation gives way around a dark circle in the floor. A rope shifts against the well’s rim; nearby, somebody is explaining a route with crumbs and a knife. Behind the bar, a man watches the room as if he has heard enough brave plans to value the quiet ones.'],
      ask:['Are you looking for a table, a message, work, or information about the well?','Which story about the journey do you choose to tell here?'],
      run:['Durnan’s immediate concern is practical: what do they need, and who should be told if an expedition is late? He is experienced, not omniscient.',
        'Offer food/lodging terms or hold a message through an actual agreement. Check the local book for any fee before charging; this scene does not debit the party.',
        'Show one sign of an inhabited expedition hub: someone repairing a pack, a returned party paying a debt, or a map disagreement. Do not introduce all recurring patrons at once.',
        'If they ask about a first descent, offer a bounded survey interview and use wd-brief for readiness. The group can stay above ground; no compulsory brawl or fall into the well.',
        'Kestrel’s crew can be seen or introduced later if wanted. No rival steals from them just to announce importance.',
        'Use the published entrance procedures if they choose the well; the transition itself neither stages monsters nor grants safe passage.'],
      choices:['Settle in and wait for the agreed contact.','Ask about legitimate work or one chosen rumor.','Leave a message and explore another city lead.'],
      private:[custom,'Printed Portal and entrance foundation: Dungeon of the Mad Mage pp.6–9. Narration and ordinary activity here are original.'],source:[mage(6),mage(7)],
      decisions:[{label:'Seek descent work',consequence:'Prepare a contract and readiness review; no immediate dungeon reset.'},{label:'Stay social',consequence:'Choose one conversation and let the city be a place to live.'}]},
    {id:'tr-dracuseth',title:'Dracuseth · hear the account before interpreting it',scene:'wd-contact',media:['recorded-tavern'],questIds:['act-home','courtyard'],
      tv:'Show the existing Dracuseth portrait only when this meeting actually occurs; private messages remain private.',
      read:['Dracuseth moves a chair out from the table. “You have had a long road. Tell me what happened in your words. I can wait until you have eaten.”'],
      ask:['What do you tell him about Phandalin? What help do you actually want?','Would you like an introduction to a place to stay, or do you prefer your own arrangements?'],
      run:['Run the meeting only once it is arranged or a believable message has reached him. If he is occupied, leave a note and let the party choose another lead.',
        'His intention is to provide a dependable city contact without taking over. He listens before making suggestions and knows only the information actually shared.',
        'Offer one concrete service: keep a sealed message, arrange a chosen introduction, check on a named city person, or introduce courtyard lodgings. Agree scope and a way to contact him.',
        'He remains in Waterdeep, lives nearby and visits; he is not the sixth adventurer, the party’s landlord, or an unseen dungeon rescuer.',
        'If asked about mysterious evidence, he can admit uncertainty and suggest a suitable specialist. He neither identifies the Nine nor explains Aldric’s return.',
        'If they welcome the lodging introduction, use tr-courtyard. If they decline, the same contact remains available without resentment.'],
      choices:['Accept the courtyard introduction.','Ask for a different practical service.','Keep the meeting friendly and make no commitment.'],
      private:[custom,'Do not introduce Mara’s private approach here unless she has a credible way to know the relevant information and Trista wants that spotlight.'],source:[],
      decisions:[{label:'Agree help',consequence:'Record the precise promise and who can call on it.'},{label:'Decline lodging',consequence:'Portal rooms or another chosen base remain valid; home scenes can adapt later.'}]},
    {id:'tr-courtyard',title:'Mending Court · a doorway they can choose',scene:'city-waterdeep',media:['recorded-town'],questIds:['act-home','courtyard'],
      tv:'Use the Waterdeep map as contextual staging. There is no dedicated courtyard image; this view is not an exact courtyard floor plan.',
      read:['A passage opens into a small court shared by several doorways. Washing moves above a well. A covered table bears a repair someone has not finished, and the space smells faintly of paste, wood and somebody’s supper. Dracuseth pauses at the entrance. “People live here. See if you would like to be among them.”'],
      ask:['What do you look at first: the rooms, the shared space, access and storage, or the neighbors?','What terms would make this useful without tying you to a life you have not chosen?'],
      run:['Mending Court is the approved proposed name for this custom neighborhood, within walking distance of the Portal. Keep exact street and ward open until placed deliberately; it is not automatically Trollskull Manor.',
        'Dracuseth provides the introduction. A responsible local lessor must agree any rental; he does not own the party’s home. Establish rooms, occupancy, rent/deposit, locks, storage, access and notice before moving anyone or money.',
        'Use ordinary terms chosen at the table, reviewed against existing prices if wanted. The campaign has not already awarded a property or paid a deposit.',
        'Introduce only Nessa Brindle and Orenna Pike now. Nessa wants steady bookbinding orders and time for an apprentice; Orenna wants deliveries and passage kept workable.',
        'Let the party inspect and refuse. They can rent temporarily, use it as a contact address by agreement, stay at the Portal, or seek somewhere else.',
        'Do not introduce supernatural anomalies on arrival. Establish ordinary geography, boundaries and relationships first.'],
      choices:['Negotiate a short rental.','Ask for a later visit and compare other lodgings.','Decline and keep only the introduction.'],
      private:[custom,'Nessa, Orenna, Jori/Pellan and Aven are independent people. They are not replacements for Halaster’s family or secretly agents by default.'],source:[],
      decisions:[{label:'Accept terms',consequence:'Review actual cost and consent; record address, access and custody separately.'},{label:'Delay choice',consequence:'No lease or expense is applied; the next meeting remains possible.'}]},
    {id:'tr-neighbors',title:'Two neighbors · a small thing that makes a home',scene:'city-waterdeep',media:['recorded-town'],questIds:['courtyard','character-pebble','character-ringgo','character-donavan'],
      tv:'Keep the contextual city view; player-shared notes may name only residents introduced in play.',
      read:['Nessa studies the legs of a heavy press while Orenna studies the space it is blocking. “It must go somewhere,” Nessa says. “Agreed,” Orenna replies, “but somewhere is not the middle of the passage.” Their disagreement has the comfortable sound of one that expects to be solved.'],
      ask:['Do you help, offer an idea, or leave the neighbors to their work?','If you stay here, what one small change would make the space feel like yours?'],
      run:['This is an ordinary collaborative task, not a test of worthiness. Nessa needs the press moved safely into a prepared work area; Orenna wants access wide enough for deliveries and anyone needing assistance.',
        'A safe plan with enough willing hands can work without a check. Show pinch points and fragile equipment before a risky attempt; agree repair cost rather than silently damaging a character’s property.',
        'Pebble’s strength or tool knowledge can help without making him compulsory labor. Ringgo can coordinate access; Donavan can measure; any character can contribute or politely decline.',
        'Let neighbors offer practical thanks: local directions, a place for a message, or an invitation to sit. No automatic intimate trust, patronage or hidden clue.',
        'If the party settles, ask what each unpacks and where they prefer to sit; each can pass. Introduce Jori and their adult brother Pellan at a later meal, or Aven during another ordinary visit, not in a six-NPC greeting line.',
        'Save only actual names, favors and chosen improvements. The first return can build recognition; later promises build trust.'],
      choices:['Help with the press or clear the passage.','Offer another useful contribution.','Keep introductions brief and rest.'],
      private:[custom,'No anomaly, attack, ancestral revelation or compulsory emotional attachment is needed. The original press scene is unrelated to a published treasure award.'],source:[],
      decisions:[{label:'Help',consequence:'Record the specific favor and response, not instant lifelong friendship.'},{label:'Choose an improvement',consequence:'Create a proposed downtime project; apply spending and completion only after review.'}]},
    {id:'tr-next',title:'The next morning · choose what the city is for',scene:'wd-portal',media:['recorded-tavern'],questIds:['act-home','courtyard','route','second-opinion','instrument'],
      tv:'Stage the place the party actually chose to meet; wd-portal is the default only when they go there. Show one approved main objective.',
      read:['The city is already at work when the next page of your plans is opened. There is room for two appointments, perhaps one useful errand, and whatever the day refuses to keep tidy.'],
      ask:['What do you want to accomplish next, and what would make you turn back or change course?','What news or help should go back to Phandalin?'],
      run:['Choose two or three likely leads for the next preparation board: a bounded survey interview, Second Margin research, Ninepin examination, a personal records inquiry, settling the lodgings, or returning to unfinished Phandelver work.',
        'Reuse wd-research, wd-workshop and wd-brief for the selected meetings. Avoid replaying an arrival that already happened or moving every patron to the same table.',
        'Before Undermountain, review actual levels, gear, light, resources, fee, return contact and abort conditions. The main adventure normally begins around level 5; opening this pack grants no advancement.',
        'The first survey is one reachable stretch and a return. Preserve the published floor, actual routes and local factions; the Echo remains a question among lived-in dungeon problems.',
        'Close using the session review: actual arrivals, relationships, promises, custody, travel costs, approved discoveries and unresolved requests. Draft the next recap from approved events only.',
        'A rejected lead gets its honest alternative. A decision to stay above ground or return to Phandalin is a prepared continuation.'],
      choices:['Prepare a bounded first expedition.','Spend a city day on research, work or home.','Return to unfinished people and problems in Phandalin.'],
      private:[custom,'Do not advance the campaign act or complete the prologue merely because Waterdeep appears on screen. The party may seek aid before finishing its earlier work.'],source:[mage(6),mage(7)],
      decisions:[{label:'Choose the next session',consequence:'Assemble and review its board; keep unresolved outcomes and personal secrets intact.'},{label:'End this evening',consequence:'Use the editable closing review and preserve the current scene and resources.'}]}
  ];
  globalThis.ECHO_TRANSITION_DATA = {
    version:1,title:'From Phandalin to Waterdeep',status:'future-preparation',
    authority:'Latest DM-confirmed play: Gundren was left at an unnamed inn, Trista holds Glasstaff’s captured rat, and the party stopped at Barthen’s Provisions. Glasstaff escaped to Cragmaw Castle, a DM-only destination. Gundren’s present condition is unreported. Echo-Below-Campaign-Outline.md governs future story choices. All read-aloud here is original; source references identify published setting and rules anchors only.',
    defaults:Object.fromEntries(outcomes.map(row=>[row.id,'unknown'])),
    outcomes,leads,beats,
    homecomings:[
      {id:'neutral',title:'News before conclusions',when:'Any unanswered outcome; default.',read:'People make room for your account. Someone brings water. No one raises a toast before they know whose names belong in it.',run:'Use tr-homecoming. Ask what the party shares; do not fill unknown fates.'},
      {id:'success',title:'A celebration with names remembered',when:'Only when rescues and the relevant mine success are approved and publicly shared.',read:'A small cheer begins at one table and travels farther than its first speaker intended. Then someone makes room for the names of those who will not hear it, and the noise softens into something worth keeping.',run:'Let players choose the celebration. Include Tharden only if his death has actually been learned and disclosed; any other loss needs its own confirmed record.'},
      {id:'mixed',title:'Gratitude beside grief',when:'Confirmed help or rescue coexists with a confirmed loss.',read:'Thanks and condolences arrive in the same conversation. A meal is offered, a chair is left quiet, and people begin asking what they can do now.',run:'Name only confirmed losses and present survivors. Give practical care and remembrance equal room.'},
      {id:'unfinished',title:'A return for help',when:'Rescue, hazards, access or opposition remain unresolved.',read:'The map is brought closer to the lamplight. “Start with where you stopped,” someone says. “Then tell us what you need to go back.”',run:'Offer one realistic form of help from a willing available person. Preserve the dungeon save; no completion reward or respawn.'}
    ],
    staging:{
      scenes:['town-phandalin','lmop-stonehill-common-room','region-lmop','cover','city-waterdeep','wd-portal','wd-contact','wd-research'],
      media:['recorded-town','recorded-journey','recorded-tavern','recorded-investigation','recorded-fire','recorded-forest'],
      note:'Use existing visual previews before Show on TV. Neutral cover stages travel; the existing Waterdeep overview gives context for the courtyard. These are not surveyed regional or courtyard maps. No new artwork or mandatory combat pack is required.'
    }
  };
})();
